import datetime
try:
    H = ['2026-10-26', '2026-11-11', '2026-11-26', '2026-12-25', '2027-01-01']
    one = datetime.timedelta(days=1)
    t = datetime.date.fromisoformat(str(vars.get('now'))[:10])
    bds = []
    d = t
    while len(bds) < 12:
        d = d + one
        if d.weekday() < 5 and d.isoformat() not in H:
            bds.append(d)
    fri = t + datetime.timedelta(days=4 - t.weekday())
    a1 = None
    for x in bds:
        if x <= fri:
            a1 = x
    if a1 is None:
        for x in bds:
            if x <= fri + datetime.timedelta(days=7):
                a1 = x
    lines = []
    d = t
    while d <= bds[11]:
        good = d.weekday() < 5 and d.isoformat() not in H
        lines.append(d.strftime('%A %Y-%m-%d') + (' business day' if good else ' NOT a business day'))
        d = d + one
    today_ok = t.weekday() < 5 and t.isoformat() not in H
    vars['date_facts'] = chr(10).join(['Today: ' + t.strftime('%A %Y-%m-%d') + (' (business day, a valid promise date)' if today_ok else ' (not a business day)'), 'Deadline, early band (days_late 1 to 7): ' + bds[11].strftime('%A %Y-%m-%d'), 'Deadline, late band (days_late 8 to 45): ' + bds[6].strftime('%A %Y-%m-%d'), 'Attempt 1 date: ' + a1.strftime('%A %Y-%m-%d'), 'Calendar:'] + lines)
except Exception:
    vars['date_facts'] = 'Now is ' + str(vars.get('now')) + '. Work out the dates from the rules.'

